{
  "hechos": [
    {
      "id": "H1",
      "texto": "Todo el casco urbano de San Aurelio quedó sin agua potable.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H2",
      "texto": "El acueducto cortó el suministro de agua.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H3",
      "texto": "En la planta El Retiro se encontraron niveles de mercurio por encima del límite permitido.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H4",
      "texto": "Unos 18.000 usuarios del servicio están sin agua.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H5",
      "texto": "La contaminación se había detectado un mes atrás.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H6",
      "texto": "Se calcula que pasarán al menos tres días antes de que vuelva el agua.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H7",
      "texto": "Ramiro Cárdenas, integrante de la junta comunal del barrio Villa Nueva, contó a Noticias al Instante que desde la madrugada hay filas frente a los carrotanques.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H8",
      "texto": "Fabio Patiño, comerciante del barrio Santa Rita, contó a Alerta Nacional Ya que varias familias están recogiendo agua lluvia en baldes.",
      "tipo": "atribucion",
      "paginas": ["P5"]
    },
    {
      "id": "H9",
      "texto": "Hernán Galindo, comerciante del barrio Las Brisas, contó a InfoExprés que varias familias están recogiendo agua lluvia en baldes.",
      "tipo": "atribucion",
      "paginas": ["P6"]
    }
  ]
}
